using System;using System.IO;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
[InitializeOnLoad] public static class MorayPCLiveCheck {
 const string Key="Underwater.MorayPCLiveCheck",Output="Renders/MorayPCProof/";static CurledMorayEncounter eel;static Vector3[] initial;static double began,stageStart;static int stage;static bool failed;static float deformation,pausedClock;static FieldInfo menuField=typeof(Diver).GetField("menu",BindingFlags.NonPublic|BindingFlags.Instance);
 static MorayPCLiveCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=Changed;}
 public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");EditorApplication.EnterPlaymode();}
 static void Changed(PlayModeStateChange mode){if(mode==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);EditorApplication.Exit(failed?1:0);}}
 static Vector3[] Points(){var pts=OctopusRepairValidation.Points(eel.skin);for(int i=0;i<pts.Length;i++)pts[i]=eel.transform.InverseTransformPoint(pts[i]);return pts;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||Time.timeSinceLevelLoad<2)return;
 try{
 if(!eel){eel=UnityEngine.Object.FindFirstObjectByType<CurledMorayEncounter>();if(!eel||!Diver.Instance)throw new Exception("Runtime moray/diver missing");Directory.CreateDirectory(Output);menuField.SetValue(Diver.Instance,false);began=stageStart=EditorApplication.timeSinceStartup;initial=Points();stage=0;return;}
 double elapsed=EditorApplication.timeSinceStartup-stageStart;if(EditorApplication.timeSinceStartup-began>65)throw new Exception("Live moray test timed out in "+eel.State);
 if(stage==0){var pts=Points();for(int i=0;i<pts.Length;i++)deformation=Mathf.Max(deformation,(pts[i]-initial[i]).magnitude);if(elapsed<3)return;if(eel.AnimationClock<1||deformation<.008f)throw new Exception("Live resting animation frozen: clock="+eel.AnimationClock+" displacement="+deformation);Capture("Idle");menuField.SetValue(Diver.Instance,true);pausedClock=eel.AnimationClock;stage=1;stageStart=EditorApplication.timeSinceStartup;return;}
 if(stage==1){if(elapsed<.6)return;if(Mathf.Abs(eel.AnimationClock-pausedClock)>.001f)throw new Exception("Menu pause failed");menuField.SetValue(Diver.Instance,false);Physics.SyncTransforms();var point=eel.touchVolumes[2].bounds.center;var origin=point+Vector3.up*.35f;var ray=new Ray(origin,(point-origin).normalized);if(eel.TryDesktopTouch(new Ray(origin+Vector3.up*4,ray.direction)))throw new Exception("Desktop touch exceeds reach");var block=GameObject.CreatePrimitive(PrimitiveType.Cube);block.layer=8;block.transform.position=(origin+point)*.5f;block.transform.localScale=Vector3.one*.08f;Physics.SyncTransforms();bool throughRock=eel.TryDesktopTouch(ray);UnityEngine.Object.DestroyImmediate(block);Physics.SyncTransforms();if(throughRock)throw new Exception("Desktop touch through rock");if(!eel.TryDesktopTouch(ray))throw new Exception("PC click handler failed: "+eel.LastPlanFailure);stage=2;stageStart=EditorApplication.timeSinceStartup;return;}
 if(stage==2){if(eel.State==CurledMorayEncounter.Phase.Swimming&&elapsed>4&&!File.Exists(Output+"Swimming.png"))Capture("Swimming");if(eel.CompletedEscapes==0)return;if(eel.State!=CurledMorayEncounter.Phase.Resting||eel.LastTravel<2)throw new Exception("Live PC escape did not settle");Capture("Settled");File.WriteAllText(Output+"Validation.txt","Actual Play-mode Update advanced resting animation: max local vertex displacement="+deformation+" m, clock="+eel.AnimationClock+" s.\nMenu paused animation. PC ray click used the production desktop-touch handler; reach and occlusion checks passed.\nReal Update loop completed escape, swimming, curl and ground settling; travel="+eel.LastTravel+" m.\nSkin: specular highlights and glossy reflections disabled; normal depth=0.25; smoothness=0.08.\n");Debug.Log("MORAY_PC_LIVE_VALIDATED deformation="+deformation+" travel="+eel.LastTravel);EditorApplication.ExitPlaymode();}
 }catch(Exception e){failed=true;Debug.LogException(e);EditorApplication.ExitPlaymode();}}
 static void Capture(string name){var cam=new GameObject("Temporary moray live test camera").AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.enabled=false;cam.fieldOfView=45;var center=eel.skin.bounds.center;cam.transform.position=center+eel.transform.right*2+Vector3.up*1.1f;cam.transform.LookAt(center);ReefCorrectionAudit.Capture(cam,Output+name+".png");UnityEngine.Object.DestroyImmediate(cam.gameObject);}
}
}
